}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// GET ONE — POST /one_leadCaptures (added for detail view)
export async function getOneLeadCapture(leadCaptureId: number, companyId: number): Promise<LeadCapture | null> {
  const res = await fetch(BASE_URL + "/one_leadCaptures", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "leadCaptureId": leadCaptureId, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json(); // It returns {leadCaptures: [one]}
  return data.leadCaptures && data.leadCaptures.length > 0 ? data.leadCaptures[0] : null;
}

