export async function createLeadCapture(payload: Omit<LeadCapture, "leadCaptureId" | "created_At" | "updated_at">): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) {
    const errorBody = await res.json();
    throw new Error(errorBody.error || "Error al crear lead.");
  }
  return await res.json();
}

