    try {
      const fetchedLead = await getOneLeadCapture(lead.leadCaptureId, companyId);
      if (fetchedLead) {
        setSelectedLead(fetchedLead);
        setFormState({ ...fetchedLead }); // Populate form with existing data
        setShowCreateEditModal(true);
      } else {
        setError("No se pudo cargar el detalle del lead.");
      }
    } catch (err) {
      setError((err as Error).message ?? "Error al cargar el lead para editar.");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setError('');
    setSuccessMessage('');

    // Basic form validation
    if (!formState.fullName || !formState.email || !formState.leadSource || !formState.status) {
      setError('Por favor, completa todos los campos obligatorios (Nombre Completo, Email, Fuente, Estado).');
      setSaving(false);
      return;
    }
    if (!formState.privacyConsentAccepted) {
      setError('Debe aceptar la política de privacidad.');
      setSaving(false);
      return;
    }

    try {
      if (selectedLead) {
        // Update existing lead
        await updateLeadCapture(selectedLead.leadCaptureId, {
          ...formState, // Send all relevant fields for update
          companyId: undefined, // companyId is not updated via payload directly as per CRUD_ONLY pattern for update action
          leadCaptureId: undefined, 
          created_At: undefined, 
          updated_at: undefined, 
        });
        setSuccessMessage('Lead actualizado con éxito.');
      } else {
        // Create new lead
        await createLeadCapture({
          ...formState as Omit<LeadCapture, "leadCaptureId" | "created_At" | "updated_at">,
          companyId: companyId, // Ensure companyId is passed for creation for internal tools
          active: true,
        });
        setSuccessMessage('Lead creado con éxito.');
      }
      setShowCreateEditModal(false);
      fetchLeads(true, 1); // Refresh the list
      resetForm();
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el lead.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (leadToDeleteId === null) return;
    setDeleting(true);
    setError('');
    setSuccessMessage('');
    try {
      await deleteLeadCapture(leadToDeleteId, companyId);
      setSuccessMessage('Lead eliminado con éxito.');
      fetchLeads(true, 1); // Refresh the list
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar el lead.');
    } finally {
      setDeleting(false);
      setLeadToDeleteId(null);
      setShowDeleteAlert(false);
    }
  };

  const triggerDelete = (id: number) => {
    setLeadToDeleteId(id);
    setShowDeleteAlert(true);
  };

  const getStatusBadgeColor = (status: string) => {
    const statusOption = LEAD_STATUS_OPTIONS.find(opt => opt.value === status);
    return statusOption ? statusOption.color : 'medium';
  };

  const hasLeads = leads.length > 0;

  return (
    <IonPage className="lead-capture-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Gestión de Leads — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          value={searchTerm}
          onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSearchTerm(e.detail.value!)}
          placeholder="Buscar leads por nombre o email"
          debounce={300}
          className="lead-capture-searchbar"
          animated
        />

        <div className="lead-capture-filters">
          <IonSelect
            fill="outline"
            label="Filtrar por Estado"
            labelPlacement="floating"
            value={statusFilter}
            onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setStatusFilter(e.detail.value)}
            className="lead-capture-filter-select"
          >
            <IonSelectOption value={undefined}>Todos</IonSelectOption>
            {LEAD_STATUS_OPTIONS.map(option => (
              <IonSelectOption key={option.value} value={option.value}>
                {option.label}
              </IonSelectOption>
            ))}
          </IonSelect>

          <IonSelect
            fill="outline"
            label="Filtrar por Área de Interés"
            labelPlacement="floating"
            value={interestAreaFilter}
            onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setInterestAreaFilter(e.detail.value)}
            className="lead-capture-filter-select"
          >
            <IonSelectOption value={undefined}>Todos</IonSelectOption>
            {INTEREST_AREAS.map(option => (
              <IonSelectOption key={option.value} value={option.value}>
                {option.label}
              </IonSelectOption>
            ))}
          </IonSelect>
        </div>

        {loading && !hasLeads ? (
          <div className="ion-text-center ion-padding">
            <IonSpinner name="crescent" />
            <p>Cargando leads...</p>
          </div>
        ) : leads.length === 0 ? (
          <div className="ion-text-center ion-padding">
            <IonIcon icon={informationCircleOutline} size="large" color="medium" />
            <p>No se encontraron leads.</p>
            <IonButton expand="block" onClick={handleCreateClick}>
              <IonIcon icon={add} slot="start" /> Crear Nuevo Lead
            </IonButton>
          </div>
        ) : (
          <IonList className="lead-capture-list">
            {leads.map(lead => (
              <IonItem key={lead.leadCaptureId} lines="full" className="lead-capture-item">
                <IonAvatar slot="start">
                  <IonImg src={`https://www.gravatar.com/avatar/${btoa(lead.email)}?d=identicon`} />
                </IonAvatar>
                <IonLabel>
                  <h2>{lead.fullName}</h2>
                  <p>{lead.email}</p>
                  {lead.companyName && <IonNote>{lead.companyName}</IonNote>}
                  <div className="lead-capture-item-details">
                    {lead.leadSource && <IonChip className="lead-capture-chip">{lead.leadSource}</IonChip>}
                    <IonBadge color={getStatusBadgeColor(lead.status)} className="lead-capture-status-badge">
                      {LEAD_STATUS_OPTIONS.find(opt => opt.value === lead.status)?.label || lead.status}
                    </IonBadge>
                  </div>
                  <IonNote className="lead-capture-dates">
                    Creado: {toHermosillo(lead.created_At)}
                    {lead.updated_at && ` | Actualizado: ${toHermosillo(lead.updated_at)}`}
                  </IonNote>
                </IonLabel>
                <div slot="end" className="lead-capture-item-actions">
                  <IonButton fill="clear" color="primary" onClick={() => handleEditClick(lead)} disabled={saving || deleting}>
                    <IonIcon icon={pencil} slot="icon-only" />
                  </IonButton>
                  <IonButton fill="clear" color="danger" onClick={() => triggerDelete(lead.leadCaptureId)} disabled={saving || deleting}>
                    <IonIcon icon={trash} slot="icon-only" />
                  </IonButton>
                </div>
              </IonItem>
            ))}
            <IonInfiniteScroll
              ref={infiniteScrollRef}
              onIonInfinite={(ev: CustomEvent<void>) => {
                loadMoreItems();
                (ev.target as HTMLIonInfiniteScrollElement).complete();
              }}
              threshold="100px"
              disabled={!hasMore || loading}
            >
              <IonInfiniteScrollContent loadingText="Cargando más leads..." />
            </IonInfiniteScroll>
          </IonList>
        )}

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleCreateClick} disabled={saving || deleting}>
            <IonIcon icon={add} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={showCreateEditModal} onDidDismiss={() => { setShowCreateEditModal(false); resetForm(); }} className="lead-capture-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{selectedLead ? 'Editar Lead' : 'Crear Nuevo Lead'}</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={() => { setShowCreateEditModal(false); resetForm(); }}>
                  <IonIcon icon={closeCircle} slot="icon-only" />
                </IonButton>
              </IonButtons>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="lead-capture-form">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre Completo *"
                  labelPlacement="floating"
                  value={formState.fullName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, fullName: e.detail.value! }))}
                  className={!formState.fullName && saving ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.fullName && saving ? 'Nombre completo es obligatorio' : undefined}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Email *"
                  labelPlacement="floating"
                  type="email"
                  value={formState.email}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, email: e.detail.value! }))}
                  className={!formState.email && saving ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.email && saving ? 'Email es obligatorio' : undefined}
                >
                  {formState.email && (
                    // Basic email format check for UI, real validation on backend
                    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formState.email) ? (
                      <IonIcon icon={checkmarkCircle} slot="end" color="success" aria-hidden="true" />
                    ) : (
                      <IonIcon icon={warningOutline} slot="end" color="danger" aria-hidden="true" />
                    )
                  )}
                </IonInput>
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de Empresa"
                  labelPlacement="floating"
                  value={formState.companyName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, companyName: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Teléfono"
                  labelPlacement="floating"
                  type="tel"
                  value={formState.phone}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, phone: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Cargo"
                  labelPlacement="floating"
                  value={formState.jobTitle}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, jobTitle: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonTextarea
                  fill="outline"
                  label="Mensaje"
                  labelPlacement="floating"
                  value={formState.message}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, message: e.detail.value! }))}
                  rows={3}
                />
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Fuente del Lead *"
                  labelPlacement="floating"
                  value={formState.leadSource}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, leadSource: e.detail.value }))}
                  className={!formState.leadSource && saving ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.leadSource && saving ? 'Fuente del lead es obligatoria' : undefined}
                >
                  <IonSelectOption value={undefined}>Seleccione una fuente</IonSelectOption>
                  {LEAD_SOURCES.map(source => (
                    <IonSelectOption key={source.value} value={source.value}>
                      {source.label}
                    </IonSelectOption>
                  ))}
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Área de Interés"
                  labelPlacement="floating"
                  value={formState.interestArea}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, interestArea: e.detail.value }))}
                >
                  <IonSelectOption value={undefined}>Seleccione un área</IonSelectOption>
                  {INTEREST_AREAS.map(area => (
                    <IonSelectOption key={area.value} value={area.value}>
                      {area.label}
                    </IonSelectOption>
                  ))}
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Estado del Lead *"
                  labelPlacement="floating"
                  value={formState.status}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, status: e.detail.value }))}
                  className={!formState.status && saving ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.status && saving ? 'Estado del lead es obligatorio' : undefined}
                >
                  {LEAD_STATUS_OPTIONS.map(status => (
                    <IonSelectOption key={status.value} value={status.value}>
                      {status.label}
                    </IonSelectOption>
                  ))}
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Asignado a"
                  labelPlacement="floating"
                  value={formState.assignedTo}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, assignedTo: e.detail.value }))}
                >
                  <IonSelectOption value={undefined}>No asignado</IonSelectOption>
                  {MOCK_EMPLOYEES.map(employee => (
                    <IonSelectOption key={employee.employeeId} value={employee.employeeId}>
                      {employee.fullName}
                    </IonSelectOption>
                  ))}
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonItem lines="none" className="ion-no-padding">
                  <IonToggle
                    checked={formState.privacyConsentAccepted}
                    onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormState(p => ({ ...p, privacyConsentAccepted: e.detail.checked }))}
                    labelPlacement="end"
                  >
                    Consentimiento de privacidad aceptado *
                  </IonToggle>
                </IonItem>
                {(!formState.privacyConsentAccepted && saving) && (
                  <IonNote color="danger" className="ion-padding-start">
                    Debe aceptar la política de privacidad.
                  </IonNote>
                )}
              </div>
            </div>

            <IonButton expand="block" className="ion-margin-top" onClick={handleSave} disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : 'Guardar Lead'}
            </IonButton>
          </IonContent>
        </IonModal>

        <IonLoading isOpen={loading && !showCreateEditModal} message="Cargando..." spinner="crescent" />

        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color="danger"
        />
        <IonToast
          isOpen={!!successMessage}
          message={successMessage}
          duration={3000}
          onDidDismiss={() => setSuccessMessage('')}
          color="success"
        />

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header="Confirmar Eliminación"
          message="¿Estás seguro de que quieres eliminar este lead? Esta acción no se puede deshacer."
          buttons=[
            {
              text: 'Cancelar',
              role: 'cancel',
              cssClass: 'alert-cancel-button',
            },
            {
              text: 'Eliminar',
              cssClass: 'alert-delete-button',
              handler: handleDelete,
            },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default LeadCapturePage;
